/* From Uiverse.io by Yaya12085 - Tags: radio */
.__UIV_SCOPE__ .radio-input {
  background-color: #fff;
  padding: 20px;
  border-radius: 20px;
  display: flex;
}

.__UIV_SCOPE__ .radio-input input[type=radio] {
  display: none;
}

.__UIV_SCOPE__ .radio-input input[type=radio] + label {
  color: #333;
  font-family: Arial, sans-serif;
  font-size: 14px;
}

.__UIV_SCOPE__ .radio-input input[type=radio] + label span {
  display: inline-block;
  width: 40px;
  height: 40px;
  margin: -1px 4px 0 0;
  vertical-align: middle;
  cursor: pointer;
  border-radius: 50%;
  border: 2px solid #FFFFFF;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.33);
  background-repeat: no-repeat;
  background-position: center;
  text-align: center;
  line-height: 44px;
}

.__UIV_SCOPE__ .radio-input input[type=radio] + label span svg {
  opacity: 0;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .radio-input input[type=radio]#color-1 + label span {
  background-color: #2ecc71;
}

.__UIV_SCOPE__ .radio-input input[type=radio]#color-2 + label span {
  background-color: #3498db;
}

.__UIV_SCOPE__ .radio-input input[type=radio]#color-3 + label span {
  background-color: #f1c40f;
}

.__UIV_SCOPE__ .radio-input input[type=radio]:checked + label span svg {
  opacity: 1;
}

.__UIV_SCOPE__ .radio-input:has(input[type=radio]#color-1:checked) {
  background-color: #2ecc71;
}

.__UIV_SCOPE__ .radio-input:has(input[type=radio]#color-2:checked) {
  background-color: #3498db;
}

.__UIV_SCOPE__ .radio-input:has(input[type=radio]#color-3:checked) {
  background-color: #f1c40f;
}
